  "query": "SELECT Id, CaseNumber, Status, Account.Name, Policy__r.Id, Policy__r.Name, Policy__r.Expiration_Date__c FROM Case WHERE RecordType.DeveloperName = 'Claim' AND IsClosed = false AND Policy__r.Expiration_Date__c >= 2026-10-02 AND Policy__r.Expiration_Date__c <= 2026-12-31 ORDER BY Policy__r.Expiration_Date__c LIMIT 50"
